import{_ as a,o as e,c as s,a6 as n}from"./chunks/framework.DL_pga9_.js";const h=JSON.parse('{"title":"Standard Library","description":"","frontmatter":{},"headers":[],"relativePath":"guide/standard-library.md","filePath":"guide/standard-library.md","lastUpdated":1781686130000}'),i={name:"guide/standard-library.md"};function l(r,t,d,o,p,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="standard-library" tabindex="-1">Standard Library <a class="header-anchor" href="#standard-library" aria-label="Permalink to “Standard Library”">​</a></h1><p>NG includes a small but capable standard library organized into modules. The library is written in NG itself, with some primitives backed by native (C++) implementations.</p><h2 id="module-overview" tabindex="-1">Module Overview <a class="header-anchor" href="#module-overview" aria-label="Permalink to “Module Overview”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lib/</span></span>
<span class="line"><span>├── std.ng              # Root module re-exporting all sub-modules</span></span>
<span class="line"><span>└── std/</span></span>
<span class="line"><span>    ├── prelude.ng       # Auto-imported basics (print, assert, not, len)</span></span>
<span class="line"><span>    ├── io.ng            # File and terminal I/O</span></span>
<span class="line"><span>    ├── string.ng        # String manipulation</span></span>
<span class="line"><span>    ├── array.ng         # Array operations</span></span>
<span class="line"><span>    ├── list.ng          # Linked list</span></span>
<span class="line"><span>    ├── seq.ng           # Sequence operations</span></span>
<span class="line"><span>    ├── tuple.ng         # Enhanced tuple operations</span></span>
<span class="line"><span>    └── memory.ng        # Memory management utilities</span></span></code></pre></div><h2 id="prelude-auto-imported" tabindex="-1">Prelude (Auto-Imported) <a class="header-anchor" href="#prelude-auto-imported" aria-label="Permalink to “Prelude (Auto-Imported)”">​</a></h2><p>The <code>std.prelude</code> module is <strong>implicitly imported</strong> into every NG file. It provides:</p><h3 id="print-t-args-t" tabindex="-1"><code>print&lt;T...&gt;(args: T...)</code> <a class="header-anchor" href="#print-t-args-t" aria-label="Permalink to “print&lt;T...&gt;(args: T...)”">​</a></h3><p>Prints values to stdout. Accepts any number of arguments of any type:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print(&quot;Hello&quot;);                // &quot;Hello&quot;</span></span>
<span class="line"><span>print(1, 2, 3);                // &quot;1, 2, 3&quot;</span></span>
<span class="line"><span>print(&quot;value:&quot;, 42, true);     // &quot;value: 42, true&quot;</span></span></code></pre></div><h3 id="assert-t-condition-t" tabindex="-1"><code>assert&lt;T...&gt;(condition: T...)</code> <a class="header-anchor" href="#assert-t-condition-t" aria-label="Permalink to “assert&lt;T...&gt;(condition: T...)”">​</a></h3><p>Asserts a condition is true. Crashes with a message if the first argument is falsy:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>assert(1 + 1 == 2);           // OK</span></span>
<span class="line"><span>assert(len([1, 2]) == 2);     // OK</span></span>
<span class="line"><span>// assert(false);</span><span>              // Runtime error: assertion failed</span></span></code></pre></div><h3 id="not-value-bool-bool" tabindex="-1"><code>not(value: bool) -&gt; bool</code> <a class="header-anchor" href="#not-value-bool-bool" aria-label="Permalink to “not(value: bool) -&gt; bool”">​</a></h3><p>Logical negation:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val result = not(x &gt; 0);       // equivalent to !(x &gt; 0)</span></span></code></pre></div><h3 id="len-t-xs-string-vector-t-u32" tabindex="-1"><code>len&lt;T&gt;(xs: string | vector&lt;T&gt;) -&gt; u32</code> <a class="header-anchor" href="#len-t-xs-string-vector-t-u32" aria-label="Permalink to “len&lt;T&gt;(xs: string | vector&lt;T&gt;) -&gt; u32”">​</a></h3><p>Returns the length of a string or the number of elements in an array:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print(len(&quot;hello&quot;));            // 5</span></span>
<span class="line"><span>print(len([1, 2, 3]));          // 3</span></span></code></pre></div><h2 id="i-o-std-io" tabindex="-1">I/O (<code>std.io</code>) <a class="header-anchor" href="#i-o-std-io" aria-label="Permalink to “I/O (std.io)”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.io;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>readLine() -&gt; string</code></td><td>Read a line from stdin</td></tr><tr><td><code>readFile(path: string) -&gt; string</code></td><td>Read entire file contents</td></tr><tr><td><code>writeFile(path: string, content: string) -&gt; unit</code></td><td>Write string to file (overwrites)</td></tr><tr><td><code>fileExists(path: string) -&gt; bool</code></td><td>Check if file exists</td></tr></tbody></table><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.io;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val content = readFile(&quot;data.txt&quot;);</span></span>
<span class="line"><span>print(&quot;File has&quot;, len(content), &quot;characters&quot;);</span></span></code></pre></div><h2 id="string-operations-std-string" tabindex="-1">String Operations (<code>std.string</code>) <a class="header-anchor" href="#string-operations-std-string" aria-label="Permalink to “String Operations (std.string)”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.string;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>split(s: string, delimiter: string) -&gt; vector&lt;string&gt;</code></td><td>Split by delimiter</td></tr><tr><td><code>join(items: vector&lt;string&gt;, separator: string) -&gt; string</code></td><td>Join with separator</td></tr><tr><td><code>trim(s: string) -&gt; string</code></td><td>Remove leading/trailing whitespace</td></tr><tr><td><code>contains(haystack: string, needle: string) -&gt; bool</code></td><td>Check substring</td></tr><tr><td><code>replace(s: string, old: string, rep: string) -&gt; string</code></td><td>Replace all occurrences</td></tr><tr><td><code>startsWith(s: string, prefix: string) -&gt; bool</code></td><td>Prefix check</td></tr><tr><td><code>endsWith(s: string, suffix: string) -&gt; bool</code></td><td>Suffix check</td></tr><tr><td><code>toUpper(s: string) -&gt; string</code></td><td>Convert to uppercase</td></tr><tr><td><code>toLower(s: string) -&gt; string</code></td><td>Convert to lowercase</td></tr></tbody></table><h3 id="example-1" tabindex="-1">Example <a class="header-anchor" href="#example-1" aria-label="Permalink to “Example”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.string;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val msg = &quot;Hello, World!&quot;;</span></span>
<span class="line"><span>val parts = split(msg, &quot;, &quot;);</span></span>
<span class="line"><span>print(parts[0]);                    // &quot;Hello&quot;</span></span>
<span class="line"><span>print(startsWith(msg, &quot;Hello&quot;));    // true</span></span>
<span class="line"><span>print(toUpper(msg));                // &quot;HELLO, WORLD!&quot;</span></span></code></pre></div><h2 id="array-operations-std-array" tabindex="-1">Array Operations (<code>std.array</code>) <a class="header-anchor" href="#array-operations-std-array" aria-label="Permalink to “Array Operations (std.array)”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.array;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>reverse&lt;T&gt;(xs: vector&lt;T&gt;) -&gt; vector&lt;T&gt;</code></td><td>Return reversed copy</td></tr><tr><td><code>sort&lt;T&gt;(xs: vector&lt;T&gt;) -&gt; vector&lt;T&gt;</code></td><td>Return sorted copy</td></tr><tr><td><code>isEmpty&lt;T&gt;(xs: vector&lt;T&gt;) -&gt; bool</code></td><td>Check if empty</td></tr><tr><td><code>contains&lt;T&gt;(xs: vector&lt;T&gt;, value: T) -&gt; bool</code></td><td>Check element presence</td></tr></tbody></table><h3 id="example-2" tabindex="-1">Example <a class="header-anchor" href="#example-2" aria-label="Permalink to “Example”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.array;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val arr = [3, 1, 4, 1, 5];</span></span>
<span class="line"><span>val rev = reverse(arr);</span></span>
<span class="line"><span>print(rev);                         // [5, 1, 4, 1, 3]</span></span></code></pre></div><h2 id="list-operations-std-list" tabindex="-1">List Operations (<code>std.list</code>) <a class="header-anchor" href="#list-operations-std-list" aria-label="Permalink to “List Operations (std.list)”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.list;</span></span></code></pre></div><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type List&lt;T&gt; = Nil | Cons(head: T, tail: ref&lt;List&lt;T&gt;&gt;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun listFromArray&lt;T&gt;(arr: [T]) -&gt; ref&lt;List&lt;T&gt;&gt; { ... }</span></span>
<span class="line"><span>fun listLen&lt;T&gt;(list: ref&lt;List&lt;T&gt;&gt;) -&gt; i32 { ... }</span></span></code></pre></div><h3 id="example-3" tabindex="-1">Example <a class="header-anchor" href="#example-3" aria-label="Permalink to “Example”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.list;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val lst = fromArray([1, 2, 3, 4, 5]);</span></span>
<span class="line"><span>print(listLen(lst));     // 5</span></span></code></pre></div><h2 id="sequence-operations-std-seq" tabindex="-1">Sequence Operations (<code>std.seq</code>) <a class="header-anchor" href="#sequence-operations-std-seq" aria-label="Permalink to “Sequence Operations (std.seq)”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.seq;</span></span></code></pre></div><p>Functional sequence operations:</p><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>map&lt;T, U&gt;(xs: vector&lt;T&gt;, f: (T) -&gt; U) -&gt; vector&lt;U&gt;</code></td><td>Transform each element</td></tr><tr><td><code>filter&lt;T&gt;(xs: vector&lt;T&gt;, pred: (T) -&gt; bool) -&gt; vector&lt;T&gt;</code></td><td>Keep matching elements</td></tr><tr><td><code>fold&lt;T, U&gt;(xs: vector&lt;T&gt;, init: U, f: (U, T) -&gt; U) -&gt; U</code></td><td>Left fold</td></tr><tr><td><code>reduce&lt;T&gt;(xs: vector&lt;T&gt;, f: (T, T) -&gt; T) -&gt; T</code></td><td>Reduce</td></tr><tr><td><code>flatMap&lt;T, U&gt;(xs: vector&lt;T&gt;, f: (T) -&gt; vector&lt;U&gt;) -&gt; vector&lt;U&gt;</code></td><td>Map then flatten</td></tr></tbody></table><h2 id="enhanced-tuple-operations-std-tuple" tabindex="-1">Enhanced Tuple Operations (<code>std.tuple</code>) <a class="header-anchor" href="#enhanced-tuple-operations-std-tuple" aria-label="Permalink to “Enhanced Tuple Operations (std.tuple)”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.tuple;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>is_tuple&lt;T&gt;</code></td><td>Const predicate: true if T is a tuple</td></tr><tr><td><code>tuple_size&lt;T&gt;</code></td><td>Const generic: number of elements</td></tr><tr><td><code>tuple_element&lt;T, I&gt;</code></td><td>Type of the I-th element</td></tr><tr><td><code>tuple_concat&lt;A, B&gt;</code></td><td>Concatenate two tuple types</td></tr></tbody></table><p>See <a href="./advanced-generics">Advanced Generics</a> for details.</p><h3 id="example-4" tabindex="-1">Example <a class="header-anchor" href="#example-4" aria-label="Permalink to “Example”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.tuple;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val t = (1, &quot;hello&quot;, 3.14);</span></span>
<span class="line"><span>const if (is_tuple&lt;typeof(t)&gt;) {</span></span>
<span class="line"><span>    type Second = tuple_element&lt;typeof(t), 1&gt;;</span></span>
<span class="line"><span>    // Second is string</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="memory-management-std-memory" tabindex="-1">Memory Management (<code>std.memory</code>) <a class="header-anchor" href="#memory-management-std-memory" aria-label="Permalink to “Memory Management (std.memory)”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.memory;</span></span></code></pre></div><p>Utilities for manual memory handling:</p><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>Box&lt;T&gt;</code></td><td>Heap-allocated box type</td></tr><tr><td><code>UniquePtr&lt;T&gt;</code></td><td>Unique ownership pointer with Drop</td></tr></tbody></table><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.memory;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val ptr: UniquePtr&lt;i32&gt; = nativeMalloc(8);</span></span>
<span class="line"><span>// ptr is automatically freed when it goes out of scope</span></span></code></pre></div><h2 id="ranges-and-slices-language-built-in" tabindex="-1">Ranges and Slices (Language Built-in) <a class="header-anchor" href="#ranges-and-slices-language-built-in" aria-label="Permalink to “Ranges and Slices (Language Built-in)”">​</a></h2><p>Ranges and slices are part of the language syntax, not the stdlib:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val r1 = 0..10;                  // exclusive range: 0-9</span></span>
<span class="line"><span>val r2 = 0..=10;                 // inclusive range: 0-10</span></span>
<span class="line"><span>val arr = [0, 1, 2, 3, 4, 5];</span></span>
<span class="line"><span>val slice = arr[1..4];           // span: [1, 2, 3]</span></span>
<span class="line"><span>val materialized = [...arr[..3]]; // materialize slice to vector</span></span></code></pre></div><p>See <a href="./data-structures">Data Structures</a> for more details.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><p>Continue to <a href="./orgasm-backend">ORGASM Backend</a> to learn about bytecode compilation and the VM internals.</p><blockquote><p><strong>Try it:</strong> <code>example/18.stdlib_basics.ng</code> — Standard library basics <strong>Try it:</strong> <code>example/56.stdlib_modules.ng</code> — Using multiple stdlib modules <strong>Try it:</strong> <code>example/57.ranges_slicing_pipeline.ng</code> — Range and slicing pipeline <strong>Try it:</strong> <code>example/59.std_list_sequence.ng</code> — List and sequence operations</p></blockquote>`,60)])])}const b=a(i,[["render",l]]);export{h as __pageData,b as default};
